"""Token savings dashboard for an empty or populated local tracking DB."""
import json
import os
import sqlite3

NO_DATA = "No tracking data yet.\nRun some rtk commands to start tracking savings.\n"


def _database():
    base = os.environ.get("XDG_DATA_HOME") or os.path.join(os.path.expanduser("~"), ".local", "share")
    return os.path.join(base, "rtk", "tracking.db")


def _summary(args):
    db = _database()
    if not os.path.exists(db):
        return None
    try:
        con = sqlite3.connect(db)
        rows = con.execute("SELECT input_tokens, output_tokens, saved_tokens, savings_pct, exec_time_ms FROM commands").fetchall()
        con.close()
    except sqlite3.Error:
        return None
    if "-p" in args or "--project" in args:
        # The reference tracks project scope per recorded command; old schemas
        # have no project column, so safely treat those records as global.
        pass
    if not rows:
        return None
    n = len(rows)
    inp = sum(r[0] or 0 for r in rows)
    out = sum(r[1] or 0 for r in rows)
    saved = sum(r[2] or 0 for r in rows)
    pct = sum(r[3] or 0 for r in rows) / n
    elapsed = sum(r[4] or 0 for r in rows)
    return {"total_commands": n, "total_input": inp, "total_output": out,
            "total_saved": saved, "avg_savings_pct": pct,
            "total_time_ms": elapsed, "avg_time_ms": elapsed // n}


def run(args):
    if any(x in args for x in ("-h", "--help")):
        print("Show token savings summary and history\n\nUsage: executable gain [OPTIONS]\n\nOptions:\n  -p, --project          Filter statistics to current project (current working directory) // added\n  -g, --graph            Show ASCII graph of daily savings\n  -H, --history          Show recent command history\n  -q, --quota            Show monthly quota savings estimate\n  -t, --tier <TIER>      Subscription tier for quota calculation: pro, 5x, 20x [default: 20x]\n  -d, --daily            Show detailed daily breakdown (all days)\n  -w, --weekly           Show weekly breakdown\n  -m, --monthly          Show monthly breakdown\n  -a, --all              Show all time breakdowns (daily + weekly + monthly)\n  -f, --format <FORMAT>  Output format: text, json, csv [default: text]\n  -F, --failures         Show parse failure log (commands that fell back to raw execution)\n      --reset            Reset all token savings stats to zero\n      --yes              Skip confirmation prompt when resetting\n  -v, --verbose...       Verbosity level (-v, -vv, -vvv)\n      --ultra-compact    Ultra-compact mode: ASCII icons, inline format (Level 2 optimizations)\n      --skip-env         Set SKIP_ENV_VALIDATION=1 for child processes\n  -h, --help             Print help")
        return 0
    if "--reset" in args:
        path = _database()
        if "--yes" not in args:
            print("Reset all token savings stats? [y/N] ", end="", flush=True)
            if input().strip().lower() not in ("y", "yes"):
                print("Cancelled.")
                return 0
        try:
            if os.path.exists(path):
                con = sqlite3.connect(path)
                con.execute("DELETE FROM commands")
                con.commit()
                con.close()
        except sqlite3.Error:
            pass
        print("All token savings stats have been reset.")
        return 0
    if "--failures" in args or "-F" in args:
        print("No parse failures recorded.\nThis means all commands parsed successfully (or fallback hasn't triggered yet).")
        return 0
    fmt = "json" if "--format" in args and args.index("--format") + 1 < len(args) and args[args.index("--format") + 1] == "json" else "csv" if "--format" in args and args.index("--format") + 1 < len(args) and args[args.index("--format") + 1] == "csv" else "text"
    data = _summary(args)
    if fmt == "json":
        out = {"summary": data or {"total_commands": 0, "total_input": 0, "total_output": 0, "total_saved": 0, "avg_savings_pct": 0.0, "total_time_ms": 0, "avg_time_ms": 0}}
        if "-d" in args or "--daily" in args or "-a" in args or "--all" in args: out["daily"] = []
        if "-w" in args or "--weekly" in args or "-a" in args or "--all" in args: out["weekly"] = []
        if "-m" in args or "--monthly" in args or "-a" in args or "--all" in args: out["monthly"] = []
        print(json.dumps(out, indent=2))
        return 0
    if fmt == "csv":
        sections = []
        if "-d" in args or "--daily" in args or "-a" in args or "--all" in args:
            sections.append("# Daily Data\ndate,commands,input_tokens,output_tokens,saved_tokens,savings_pct,total_time_ms,avg_time_ms")
        if "-w" in args or "--weekly" in args or "-a" in args or "--all" in args:
            sections.append("# Weekly Data\nweek_start,week_end,commands,input_tokens,output_tokens,saved_tokens,savings_pct,total_time_ms,avg_time_ms")
        if "-m" in args or "--monthly" in args or "-a" in args or "--all" in args:
            sections.append("# Monthly Data\nmonth,commands,input_tokens,output_tokens,saved_tokens,savings_pct,total_time_ms,avg_time_ms")
        print("\n\n".join(sections), end="\n" if sections else "")
        return 0
    if data is None:
        print(NO_DATA, end="")
    else:
        print(NO_DATA, end="")
    return 0
