import re
import sys


def _filter(lines, level):
    if level == 'none':
        return lines
    if level == 'minimal':
        result = []
        blank = False
        for line in lines:
            s = line.strip()
            if s.startswith(('#', '//', '/*', '*')):
                continue
            if not s:
                if not blank:
                    result.append('')
                blank = True
            else:
                result.append(line)
                blank = False
        return result
    result, body_indent = [], None
    for line in lines:
        stripped = line.strip()
        indent = len(line) - len(line.lstrip())
        if body_indent is not None:
            if stripped and indent > body_indent:
                if re.match(r'(async\s+)?def\s|class\s|fn\s|function\s|func\s', stripped):
                    result.append('    // ... implementation')
                    body_indent = None
                else:
                    continue
            elif not stripped:
                continue
            if body_indent is not None:
                result.append('    // ... implementation')
                body_indent = None
        if re.match(r'\s*(def |async def |class |fn |function |func |pub fn |impl\b)', line):
            result.append(line)
            if not stripped.startswith(('class ', 'impl ')):
                body_indent = indent
        elif stripped and not stripped.startswith(('#', '//')):
            result.append(line)
    if body_indent is not None:
        result.append('    // ... implementation')
    return result


def handle(argv):
    if '-h' in argv or '--help' in argv:
        print('''Read file with intelligent filtering

Usage: executable read [OPTIONS] <FILES>...

Arguments:
  <FILES>...  Files to read (supports multiple, like cat)

Options:
  -l, --level <LEVEL>            Filter: none (default, full content), minimal, aggressive [default: none]
  -m, --max-lines <MAX_LINES>    Max lines
      --tail-lines <TAIL_LINES>  Keep only last N lines
  -n, --line-numbers             Show line numbers
  -v, --verbose...               Verbosity level (-v, -vv, -vvv)
      --ultra-compact            Ultra-compact mode: ASCII icons, inline format (Level 2 optimizations)
      --skip-env                 Set SKIP_ENV_VALIDATION=1 for child processes (Next.js, tsc, lint, prisma)
  -h, --help                     Print help''')
        return 0
    p = argparse.ArgumentParser(prog='executable read', description='Read file with intelligent filtering')
    p.add_argument('files', nargs='+')
    p.add_argument('-l', '--level', choices=('none', 'minimal', 'aggressive'), default='none')
    p.add_argument('-m', '--max-lines', type=int)
    p.add_argument('--tail-lines', type=int)
    p.add_argument('-n', '--line-numbers', action='store_true')
    p.add_argument('-v', action='count', default=0)
    p.add_argument('--ultra-compact', action='store_true')
    p.add_argument('--skip-env', action='store_true')
    ns = p.parse_args(argv)
    status = 0
    for path in ns.files:
        original = None
        if path == '-':
            content = sys.stdin.read()
            original = content
        else:
            try:
                with open(path, encoding='utf-8', errors='replace') as f:
                    content = f.read()
                    original = content
            except OSError as e:
                print(f'cat: {path}: {e.strerror} (os error {e.errno})', file=sys.stderr)
                status = 1
                continue
        lines = _filter(content.splitlines(), ns.level)
        if ns.tail_lines is not None:
            lines = lines[-max(0, ns.tail_lines):] if ns.tail_lines else []
        truncated = ns.max_lines is not None and len(lines) > ns.max_lines
        if truncated:
            source_like = any(re.match(r'\s*(?:import|from|class|def|async\s+def|fn|function|func|struct|package)\b', x) for x in content.splitlines())
            visible = max(0, ns.max_lines - 1) if source_like else max(0, ns.max_lines // 2)
            shown = lines[:visible]
            if source_like and visible < 5:
                shown = [line for line in lines if line.strip()][:visible]
            lines = shown + [f'[{len(lines) - len(shown)} more lines]']
        if ns.line_numbers:
            lines = [f'{i} │ {line}' for i, line in enumerate(lines, 1)]
        rendered = '\n'.join(lines)
        raw_unchanged = ns.level == 'none' and ns.line_numbers is False and ns.max_lines is None
        if ns.line_numbers and lines:
            rendered += '\n'
        elif raw_unchanged:
            if original.endswith('\n') and rendered:
                rendered += '\n'
        elif lines and not (truncated and not ns.line_numbers):
            rendered += '\n'
        sys.stdout.write(rendered)
    return status
